import{_ as n,l as o,o as e,c as i,v as t,p as l,x as s,d,i as A,S as E}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"SSD 内部并行、GC 与磨损","description":"","frontmatter":{"title":"SSD 内部并行、GC 与磨损","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssd-gc-wear.md","filePath":"cs/ssd-gc-wear.md","lastUpdated":1789023840000}'),p={name:"cs/ssd-gc-wear.md"};function c(h,a,D,C,S,_){const r=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="ssd-内部并行、gc-与磨损" tabindex="-1">SSD 内部并行、GC 与磨损 <a class="header-anchor" href="#ssd-内部并行、gc-与磨损" aria-label="Permalink to &quot;SSD 内部并行、GC 与磨损&quot;">​</a></h1><div class="epigraph"><p>多通道、多颗粒、多 plane 把页编程叠起来才有带宽；垃圾回收搬走有效页再擦块，磨损均衡避免热逻辑地址写死同一物理块。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/nand-ftl">上一课</a>留下无效页与 L2P。缺口是性能与寿命：<strong>内部并行</strong>从哪来，<strong>GC</strong>何时抢用户写，<strong>磨损</strong>如何摊。否则「SSD 很快」只是广告，写放大没有定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NAND 页编程延迟远大于 DRAM 行命中，靠通道/die/plane 交错。GC：空闲块低于阈值时，选牺牲块、读有效页、写到新块、擦除牺牲块——与用户写争带宽，写放大 WA = 物理编程量 / 主机写入量。磨损：每块擦写次数有上限，热映射必须搬动物理位置。缺口不是再定义 FTL，而是这三项如何耦合。</p><p>TRIM/unmap 让主机声明 LBA 无用，减少 GC 搬移。DRAM 缓存映射加速，掉电靠电容刷回——与<a href="/cs/nvm-persistent">持久域</a>同类问题。</p><h3 id="gc-不是「磁盘碎片整理」" tabindex="-1">GC 不是「磁盘碎片整理」 <a class="header-anchor" href="#gc-不是「磁盘碎片整理」" aria-label="Permalink to &quot;GC 不是「磁盘碎片整理」&quot;">​</a></h3><p>HDD 碎片整理移动扇区以缩短寻道；SSD 没有寻道，GC 是擦除约束下的空间回收。把二者当同一 OS 工具，会在闪存上做无益的强制搬移。</p><p><span class="marginnote">CA:AQA 与 COD 讨论闪存与 SSD。写放大与磨损是存储系统常识。本课不引用虚构的百分数保证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>调度：空闲时 GC，负载时让用户写。并行：把大写条带化到通道。磨损均衡：静态（搬冷块）与动态（新写落在年轻块）。超配（OP）提供空闲块，降 WA。ECC 失败则退休块，L2P 改指。</p>',11)),(e(),l(E,null,{default:s(()=>[A(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOST%5B%22%E4%B8%BB%E6%9C%BA%E5%86%99%22%5D%20--%3E%20STRIPE%5B%22%E9%80%9A%E9%81%93%20%2F%20die%20%E6%9D%A1%E5%B8%A6%22%5D%0A%20%20INV%5B%22%E6%97%A0%E6%95%88%E9%A1%B5%E5%A0%86%E7%A7%AF%22%5D%20--%3E%20GC%5B%22%E6%90%AC%E6%9C%89%E6%95%88%E9%A1%B5%20%2B%20%E6%93%A6%E9%99%A4%22%5D%0A%20%20GC%20--%3E%20WA%5B%22%E5%86%99%E6%94%BE%E5%A4%A7%22%5D%0A%20%20WEAR%5B%22%E6%93%A6%E5%86%99%E8%AE%A1%E6%95%B0%22%5D%20--%3E%20EQ%5B%22%E7%A3%A8%E6%8D%9F%E5%9D%87%E8%A1%A1%22%5D%0A%20%20EQ%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AHDD%20%E4%BB%8D%E6%9C%89%E5%AF%BB%E9%81%93%E5%87%A0%E4%BD%95%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 DRAM FR-FCFS 对照：这里优化的是擦除与编程队列，没有行缓冲，但有 plane 忙闲。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课 HDD 用柱面/磁头/扇区与寻道；SSD 用 LBA 平板。PCIe/NVMe 把多队列打到这块并行上。本课先把介质控制器做完。BIST/工厂坏块表在出厂；现场再成长坏块由 FTL 处理。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某厂商主控固件当标准，不讨论 QLC 读干扰的全部模拟。不进入数据中心运维更换策略的财务表。</p><p>后课默认：SSD 带宽来自闪存并行；GC 与磨损均衡制造写放大和后台流量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>并行掩盖页编程延迟；GC 回收擦除块并产生写放大。</li><li>磨损均衡打散热写；TRIM 减少无用搬移。</li><li>不是磁盘碎片整理。</li><li>出处：Patterson and Hennessy, COD；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const u=n(p,[["render",c]]);export{m as __pageData,u as default};
